[CmdletBinding()]
param([Parameter(Mandatory=$true)][string]$RequestPath)
$ErrorActionPreference='Stop';$root=[IO.Path]::GetFullPath((Get-Location).Path).TrimEnd('\')+'\';$req=(Resolve-Path -LiteralPath $RequestPath -ErrorAction Stop).Path;if(-not $req.StartsWith($root,[StringComparison]::OrdinalIgnoreCase)){throw 'RequestPath must remain under project root.'}
$profilePath=Join-Path (Get-Location) '.agents/skills/es-web-ui-generation-orchestration/references/open-source-capability-profile.json';$profile=Get-Content -LiteralPath $profilePath -Raw -Encoding UTF8|ConvertFrom-Json;$request=Get-Content -LiteralPath $req -Raw -Encoding UTF8|ConvertFrom-Json
$result=[ordered]@{schemaVersion=1;recordType='ESWebOpenSourceCapabilityProfileReceipt';status='accepted';profileId=[string]$profile.profileId;requestId=[string]$request.requestId;frameworks=@($profile.frameworks);capabilities=$profile.capabilities;rendering=[ordered]@{policy=[string]$profile.capabilities.renderPolicy.default;source=@($profile.capabilities.renderPolicy.source)};components=[ordered]@{boundary=[string]$profile.capabilities.componentBoundary.default;maxHydratedRegions=[int]$profile.capabilities.resumabilityBudget.maxHydratedRegions;source=@($profile.capabilities.componentBoundary.source)};dataFlow=[ordered]@{routeContractRequired=[bool]$profile.capabilities.routeDataContract.required;fields=@($profile.capabilities.routeDataContract.fields);source=@($profile.capabilities.routeDataContract.source)};interaction=[ordered]@{stateMachineRequired=[bool]$profile.capabilities.interactionStateMachine.required;events=@($profile.capabilities.interactionStateMachine.events);source=@($profile.capabilities.interactionStateMachine.source)};progressiveEnhancement=$profile.capabilities.progressiveEnhancement;performanceBudget=$profile.capabilities.performanceBudget;nonClaims=@($profile.nonClaims);runtimeStatus='runtime-not-run'};$result|ConvertTo-Json -Depth 15
